    bronze_bookpressingweight = { name = "Bronast utež za stiskanje knjig", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast utež za stiskanje knjig za knjigoveze." },
    silver_bookpressingweight = { name = "Srebrn utež za stiskanje knjig", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn utež za stiskanje knjig za knjigoveze." },
    gilded_bookpressingweight = { name = "Pozlačen utež za stiskanje knjig", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen utež za stiskanje knjig za knjigoveze." },
