    royal_sovereign_bookpressingweight = { name = "Kraljevski suveren utež za stiskanje knjig", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren utež za stiskanje knjig z biseri za krono." },
}
