    bookpressingweight_workshop = { name = "Bookpressingweight delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    bookpressingweight_house = { name = "Bookpressingweight hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_bookpressingweight_atelier = { name = "Mojstrski bookpressingweight atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_bookpressingweight_palace = { name = "Suverena bookpressingweight palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BookPressingWeightMaker.ironStock=18; BookPressingWeightMaker.bronzeStock=14; BookPressingWeightMaker.woodStock=10; BookPressingWeightMaker.leatherStock=8; BookPressingWeightMaker.silverStock=8; BookPressingWeightMaker.goldStock=6; BookPressingWeightMaker.jewelStock=4; BookPressingWeightMaker.pearlStock=4
BookPressingWeightMaker.productStock = {}; BookPressingWeightMaker.buildings = {}; BookPressingWeightMaker.maker = nil; BookPressingWeightMaker.activeMaking = {}; BookPressingWeightMaker.totalProducts = 0; BookPressingWeightMaker.dayTimer = 0
function BookPressingWeightMaker.init() BookPressingWeightMaker.ironStock=18; BookPressingWeightMaker.bronzeStock=14; BookPressingWeightMaker.woodStock=10; BookPressingWeightMaker.leatherStock=8; BookPressingWeightMaker.silverStock=8; BookPressingWeightMaker.goldStock=6; BookPressingWeightMaker.jewelStock=4; BookPressingWeightMaker.pearlStock=4; BookPressingWeightMaker.productStock={}; BookPressingWeightMaker.buildings={}; BookPressingWeightMaker.maker=nil; BookPressingWeightMaker.activeMaking={}; BookPressingWeightMaker.totalProducts=0; BookPressingWeightMaker.dayTimer=0; print("[BookPressingWeightMaker] Royal Book Pressing Weight Maker System initialized (6 products, 4 buildings)") end
function BookPressingWeightMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookPressingWeightMaker.maker={name=n or ("Utežar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Utežar najet: %s (spretnost: %d)",BookPressingWeightMaker.maker.name,s),"success") end; return true end
function BookPressingWeightMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookPressingWeightMaker.build(id) local ok,e=BookPressingWeightMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookPressingWeightMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookPressingWeightMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookPressingWeightMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookPressingWeightMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookPressingWeightMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookPressingWeightMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookPressingWeightMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookPressingWeightMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookPressingWeightMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookPressingWeightMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookPressingWeightMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookPressingWeightMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookPressingWeightMaker.buildings==0 then return false,"Potrebna utežna delavnica" end; if not BookPressingWeightMaker.maker then return false,"Potreben utežar" end; return true end
function BookPressingWeightMaker.make(pt,qty) qty=qty or 1; local ok,e=BookPressingWeightMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookPressingWeightMaker.ironStock=BookPressingWeightMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookPressingWeightMaker.bronzeStock=BookPressingWeightMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookPressingWeightMaker.woodStock=BookPressingWeightMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookPressingWeightMaker.leatherStock=BookPressingWeightMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookPressingWeightMaker.silverStock=BookPressingWeightMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookPressingWeightMaker.goldStock=BookPressingWeightMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookPressingWeightMaker.jewelStock=BookPressingWeightMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookPressingWeightMaker.pearlStock=BookPressingWeightMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookPressingWeightMaker.maker then t=math.max(1,t-math.floor(BookPressingWeightMaker.maker.skill/13)) end; table.insert(BookPressingWeightMaker.activeMaking,{id="bookpressingweight_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookPressingWeightMaker.completeMaking(m) local q=1.0+(BookPressingWeightMaker.getQualityBonus()/100); if BookPressingWeightMaker.maker then q=q+(BookPressingWeightMaker.maker.skill/140) end; q=math.min(2.5,q); BookPressingWeightMaker.productStock[m.productType]=(BookPressingWeightMaker.productStock[m.productType] or 0)+m.quantity; BookPressingWeightMaker.totalProducts=BookPressingWeightMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookPressingWeightMaker.maker then BookPressingWeightMaker.maker.itemsMade=BookPressingWeightMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookPressingWeightMaker.maker.skill=math.min(100,BookPressingWeightMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Utež izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookpressingweight.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookPressingWeightMaker.update(dt) if not _G.state then return end; BookPressingWeightMaker.dayTimer=BookPressingWeightMaker.dayTimer+dt; if BookPressingWeightMaker.dayTimer>=30 then BookPressingWeightMaker.dayTimer=0; for i=#BookPressingWeightMaker.activeMaking,1,-1 do local m=BookPressingWeightMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookPressingWeightMaker.completeMaking(m); table.remove(BookPressingWeightMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookPressingWeightMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookPressingWeightMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookPressingWeightMaker.getStats() return {ironStock=BookPressingWeightMaker.ironStock,bronzeStock=BookPressingWeightMaker.bronzeStock,woodStock=BookPressingWeightMaker.woodStock,leatherStock=BookPressingWeightMaker.leatherStock,silverStock=BookPressingWeightMaker.silverStock,goldStock=BookPressingWeightMaker.goldStock,jewelStock=BookPressingWeightMaker.jewelStock,pearlStock=BookPressingWeightMaker.pearlStock,productStock=BookPressingWeightMaker.productStock,numBuildings=#BookPressingWeightMaker.buildings,hasMaker=BookPressingWeightMaker.maker~=nil,makerName=BookPressingWeightMaker.maker and BookPressingWeightMaker.maker.name or "—",makerSkill=BookPressingWeightMaker.maker and BookPressingWeightMaker.maker.skill or 0,activeMaking=#BookPressingWeightMaker.activeMaking,totalProducts=BookPressingWeightMaker.totalProducts} end
return BookPressingWeightMaker
